package httpserver

// authzClass is what an operation is, for the authorization matrix (#323).
// Every operation in openapi.yaml has a row in authzTable; the matrix test
// fails on an operation without one (and on a row for a removed one).
type authzClass int

const (
	// azPublic: no token needed (health, app config, sign-in, sign-up,
	// password reset, invitation preview / accept, legal documents).
	azPublic authzClass = iota
	// azPublicOff: a public route turned off by configuration in the test
	// (sign-up with TENANCY_SELF_SERVE=false): 403 for everyone.
	azPublicOff
	// azSelf: any signed-in user, on their own account only (profile,
	// sessions, MFA, passkeys, notifications, push devices, search).
	azSelf
	// azPlatform: platform administrators only (super admin permissions).
	azPlatform
	// azTenantRead: office read (X-Organization); a read-only role may.
	azTenantRead
	// azTenantReadPriv: office read that needs more than a read permission
	// (KVKK requests: tenant.privacy.request; bank branch instruction:
	// tenant.bank.write, it carries the credentials request letter).
	azTenantReadPriv
	// azTenantReadAction: a POST that only reads (account plan check, the
	// missing-accounts template, petition preview): read permission.
	azTenantReadAction
	// azTenantWrite: office write; a read-only role may not.
	azTenantWrite
	// azTenantMember: any member of the office, for themselves (leave).
	azTenantMember
	// azTaxpayerRead / taxpayerWrite: the mükellef panel (X-Taxpayer); only
	// members of that taxpayer.
	azTaxpayerRead
	azTaxpayerWrite
)

